import {translations,dynamicTranslations} from './locale-copy.js?v=locale-waterfall-v1';
const valid=['zh-Hant','en','fil'];let locale='zh-Hant';try{const saved=localStorage.getItem('gala-language-v1');if(valid.includes(saved))locale=saved}catch{}
const patterns=dynamicTranslations.map(r=>({...r,re:new RegExp(r.pattern)}));
export function translate(source){if(locale==='zh-Hant')return source;const trimmed=source.trim();if(!trimmed)return source;const column=locale==='en'?0:1;let output=translations[trimmed]?.[column];if(output===undefined)for(const r of patterns){if(r.re.test(trimmed)){const match=trimmed.match(r.re);output=r[locale].replace(/\$(\d+)/g,(_,n)=>translate(match[Number(n)]??''));break}}return output===undefined?source:source.replace(trimmed,output)}
export function languagePicker(cls=''){return `<label class="language-picker ${cls}"><span>Language / Wika</span><select data-locale-switch aria-label="Language / Wika"><option value="zh-Hant">繁體中文</option><option value="en">English</option><option value="fil">Filipino</option></select></label>`}
const sources=new WeakMap(),attributes=new WeakMap();let observer,started=false;
function translateNode(node){if(node.nodeType!==3||node.parentElement?.closest('script,style,option,[data-no-translate],.fx-stage,[aria-hidden="true"]'))return;let state=sources.get(node);if(!state||node.data!==state.last)state={source:node.data};state.last=translate(state.source);if(node.data!==state.last)node.data=state.last;sources.set(node,state)}
function scan(root){if(root.nodeType===3){translateNode(root);return}if(root.nodeType!==1&&root.nodeType!==9)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())translateNode(node);const els=root.nodeType===1?[root,...root.querySelectorAll('[title],[aria-label],[placeholder]')]:[...root.querySelectorAll('[title],[aria-label],[placeholder]')];for(const el of els){if(el.closest?.('.fx-stage,[aria-hidden="true"]'))continue;let states=attributes.get(el)||{};for(const attr of ['title','aria-label','placeholder']){if(!el.hasAttribute(attr))continue;const value=el.getAttribute(attr);let state=states[attr];if(!state||value!==state.last)state={source:value};state.last=translate(state.source);if(value!==state.last)el.setAttribute(attr,state.last);states[attr]=state}attributes.set(el,states)}for(const select of document.querySelectorAll('[data-locale-switch]'))select.value=locale}
const observe=()=>observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder']});
function apply(root=document.body){observer?.disconnect();scan(root);if(started)observe()}
export const i18n={get locale(){return locale},setLocale(next){if(!valid.includes(next))return;locale=next;try{localStorage.setItem('gala-language-v1',locale)}catch{}document.documentElement.lang=locale;apply();document.dispatchEvent(new CustomEvent('gala-language-change',{detail:{locale}}))},start(){if(started)return;started=true;observer=new MutationObserver(records=>{observer.disconnect();const roots=new Set();for(const r of records){if(r.type==='childList'){for(const n of r.addedNodes)roots.add(n)}else roots.add(r.target)}for(const root of roots)if(root.isConnected)scan(root);observe()});document.addEventListener('change',e=>{if(e.target.matches('[data-locale-switch]'))this.setLocale(e.target.value)});document.documentElement.lang=locale;apply()}};
